import pandas as pd
def get_humidity_band(val):
    if val < 60:
        return '<60'
    elif val <= 75:
        return '60-75'
    else:
        return '>=75'
df['습도구간'] = df['외기습도 (%)'].apply(get_humidity_band)
df['습도구간'] = pd.Categorical(df['습도구간'], categories=['<60', '60-75', '>=75'], ordered=True)
